"""Build the two offline HTML decks and landing page; UTF-8 throughout."""
from pathlib import Path
import json,html
ROOT=Path(__file__).resolve().parents[1]
def code(text):return '<pre><code>'+html.escape(text)+'</code></pre>'
def panel(title,text):return f'<div class="panel"><h2>{title}</h2>{text}</div>'
def cols(*items):return '<div class="grid'+(' three' if len(items)==3 else '')+'">'+''.join(items)+'</div>'
def call(text,warn=False):return '<div class="callout'+(' warn' if warn else '')+'">'+text+'</div>'
def table(headers,rows):return '<div class="table-wrap"><table><thead><tr>'+''.join('<th>'+x+'</th>' for x in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+x+'</td>' for x in r)+'</tr>' for r in rows)+'</tbody></table></div>'
def flow(items):return '<div class="flow">'+('<span class="arrow">→</span>'.join('<div class="node">'+x+'</div>' for x in items))+'</div>'
def slide(section,title,lead,body,note):return dict(section=section,title=title,lead=lead,body=body,note=note)
