L('Hafta 03 / Açılış','Task’lar konuşsun.<br><span class="accent">Veri akışını yönet.</span>','Queue, bekleme ve yük altında tasarım kararı.',cols('<div><p>İlk projeyi çalıştırdık. İz kaydında task’ları gördük. Şimdi bir verinin üreticiden tüketiciye yolculuğunu kontrol ediyoruz.</p>'+call('Ana soru: Üretici veri gönderirken tüketici yetişemezse ne olur?')+'<p class="mini">Erhan Konak · 100 dakika ders + 20 dakika mola<br>Tek çekirdek · Native FreeRTOS · STM32L476RG</p></div>','<div class="panel"><div class="hero-number">03</div><h2>Tahmin → deney → iz → açıklama</h2><p>Her sonucu bir kod kararıyla ilişkilendir.</p></div>'),'Bu hafta tek bir yeni mekanizmaya odaklanın: Queue. Mutex, event groups ve bütün senkronizasyon API’lerini aynı derse sığdırmayın.')
L('Ders haritası','İki saatlik yolculuk.','Önce ödevden öğren, sonra bir değişkeni kontrollü değiştir.',table(['Dakika','İçerik','Öğrencinin yaptığı'],[['00–15','SystemView / Traxcope ödev değerlendirmesi','İki kaydı birlikte okur'],['15–25','Ready / Running / Blocked tekrarı','“Neden çalışmıyor?” sorusunu yanıtlar'],['25–40','Queue ve veri kopyalama','Bir mesajın yolunu çizer'],['40–60','Queue işlemleri / Control block / Timeout','Mesaj ve task bekleme listelerini adımlar'],['60–80','Mola',''],['80–100','Canlı A/B/C deneyi','Tek değişkenle karşılaştırır'],['100–112','Sonuç ve bedel','Kayıp, gecikme ve üretici beklemesini yorumlar'],['112–120','Ödev ve çıkış soruları','Deney planını yazar']]),'SystemView bağlantı sorunu 3 dakikada çözülmezse paketteki gerçek donanım kaydını açın. Canlı ölçüm ve hazır kaydı açıkça ayırın.')
L('01 / Önceki ödev','Bir ekran görüntüsü değil,<br>bir neden anlat.','Öğrenci kaydından tek bir olayı birlikte takip edelim.',cols(panel('Üç soru','<p>① Task ne zaman Ready oldu?</p><p>② CPU üzerinde ne zaman Running oldu?</p><p>③ Bekleme sırasında hangi task veya ISR çalışıyordu?</p>'),panel('İyi bir açıklama','<p>“Gecikme var” yerine:</p><p>“Üretici veriyi hazırladıktan sonra tüketici henüz seçilemedi. Bu aralıkta yüksek öncelikli task çalışıyordu.”</p><p class="mini">Yalnız görüntüde kanıtlanan kısmı söyleyin; eksik trace penceresini tahminle doldurmayın.</p>')),'Gönüllü iki öğrencinin kaydını seçin. Araç menülerini karşılaştırmaktan çok olayların sırasını tartışın. Dosya/sürüm ve kayıt kaynağını görünür tutun.')
L('01 / Temel tekrar','Çalışmıyor olmak tek bir durum değil.','Scheduler yalnız çalışabilecek task’lar arasından seçim yapar.',cols(panel('Ready','<div class="big">Sıra</div><p>İş var; CPU bekleniyor.</p>'),panel('Running','<div class="big">CPU</div><p>Komutlar şu anda yürütülüyor.</p>'),panel('Blocked','<div class="big">Olay</div><p>Veri, yer veya süre bekleniyor.</p>'))+call('Queue üzerinde bloklanan yüksek öncelikli üretici, düşük öncelikli tüketicinin çalışmasına fırsat verebilir.'),'Sorun: “Producer P2, Consumer P1. Producer queue doluyken bloklanırsa Consumer çalışabilir mi?” Cevap: Evet, daha yüksek başka Ready task yoksa.')
L('02 / Mimari','İki task, bir veri yolu.','Queue üretici ve tüketicinin doğrudan aynı değişken üzerinden haberleşmesini gerektirmez.',flow(['Producer<small>Message üretir</small>','MessageQueue<small>Sınırlı sayıda kopya saklar</small>','Consumer<small>Alır ve işler</small>'])+cols(panel('Üretici','<p>Veriyi hazırlar. Göndermeyi dener. Başarılı mı kontrol eder.</p>'),panel('Tüketici','<p>Veriyi almayı bekler. Aldığı kendi kopyasını işler.</p>')),'Her fonksiyon ayrı task değildir. Burada iki ayrı görev rolü seçiyoruz. Console yalnız komut ve deney sonrası aktarım için üçüncü task’tır.')
L('02 / Queue','Queue bir bekleme odasıdır.','Bir elemanın boyutu ve toplam eleman sayısı oluşturma anında belirlenir.',code('typedef struct {\n    uint32_t sequence;\n    uint32_t generated_us;\n    uint32_t value;\n} Message;\n\nQueueHandle_t q = xQueueCreate(4, sizeof(Message));\nconfigASSERT(q != NULL);')+call('Bu hedefte Message = 12 bayt; 4 eleman için veri alanı 48 bayt. Kernel yönetim bilgisi ve allocator ek yükü ayrıca RAM kullanır.'),'Native FreeRTOS queue boyutu byte olarak item size + item count ile belirlenir. Task stack derinliğinin eleman cinsinden olmasıyla karıştırmayın. Dinamik oluşturma başarısız olabilir.')
L('02 / Veri sahipliği','Gönderilen kopya bağımsızdır.','Yerel değişkeni sonradan değiştirmek kuyruğa alınan struct’ı değiştirmez.',cols('<div class="panel"><h2>Üreticinin nesnesi</h2><div class="big" id="copyValue">42</div><div class="controls"><button id="copySend" class="primary">Queue’ya kopyala</button><button id="copyChange">Yerel değeri değiştir</button></div></div>','<div class="panel"><h2>Kuyruktaki kopya</h2><div class="big" id="queueValue">—</div><p id="copyStatus" role="status">Önce bir değer gönderin.</p></div>')+call('Pointer kuyruğu farklıdır: pointer değeri kopyalanır; işaret edilen buffer kopyalanmaz. Bu hafta struct’ı değer olarak taşıyoruz.'),'Önce 42’yi gönderin, sonra yerel nesneyi 99 yapın. Queue değerinin 42 kaldığını gösterin. Pointer ömrünü ayrıntılı zorunlu ödeve çevirmeyin.')
L('03 / Üretici','xQueueSend(): sonuç önemlidir.','Kuyruğa veri yazmayı denemek, verinin mutlaka kabul edildiği anlamına gelmez.',code('Message msg = { .sequence = 1, .value = 42 };\n\nBaseType_t result = xQueueSend(q, &msg, 0);\nif (result == pdPASS) {\n    accepted++;\n} else {\n    failed++;\n}')+cols(panel('Yer varsa','<p>Mesaj kopyalanır. Başarılı dönüş alınır.</p>'),panel('Doluysa ve bekleme 0 ise','<p>Task yer açılmasını beklemez. Çağrı başarısız döner; uygulama karar vermelidir.</p>')),'failed sayacı burada gönderme girişimi başarısızlığıdır. Kayıt almadan sessizce yok saymak verinin akıbetini belirsiz yapar. Dönüş değerini mutlaka kontrol edin.')
L('03 / Tüketici','xQueueReceive(): boşken ne olacak?','Bekleme süresi seçimi, tüketicinin boş kuyruktaki davranışını belirler.',code('Message msg;\nif (xQueueReceive(q, &msg, pdMS_TO_TICKS(25)) == pdPASS) {\n    ProcessMessage(&msg);\n} else {\n    // 25 tick hedefi boyunca veri gelmedi.\n    // Normal akış veya uygulamaya uygun timeout yolu.\n}')+call('Bu firmware’de tick 1 kHz. Bekleme süreleri tick cinsindedir; timeout sonrasında task’ın CPU alması ayrıca scheduler’a bağlıdır.'),'ProcessMessage öğretim örneği fonksiyondur. Gerçek laboratuvar consumer kodunda 20 ms vTaskDelay kullanılır. Genel projelerde ms ve tick’i eşit varsaymayın.')
L('04 / Yük','Ortalama hız yetmez; burst de önemlidir.','Tüketici aynı anda yalnız bir mesajı işler.',cols(panel('Normal yük','<div class="big">100 ms</div><p>İki gönderme girişimi arası bekleme. Tüketicinin modellenen servis beklemesi 20 ms.</p>'),panel('Yoğun bölüm','<div class="big">24</div><p>Art arda gönderme girişimi. Üretici 0 tick politikasında hazır kalır; küçük kuyruk hızlı dolar.</p>'))+call('Kalıcı üretim hızı tüketim hızını aşarsa hiçbir sonlu kuyruk sınırsız süre boyunca kayıpsız depolayamaz.'),'Bu deneyde burst, 24 gönderme girişimidir. C’de gönderme çağrısı bloklandığı için fiziksel girişim zamanları uzar; bunu adil olmayan deney diye saklamayın, politikanın sonucu olarak raporlayın.')
L('04 / Mola','20 dakika mola.','Dönüşte tahminlerimizi aynı kart üzerinde sınayacağız.',cols('<div class="hero-number">20′</div>',panel('Dönüş sorusu','<p>Kuyruğu 4’ten 16’ya çıkarmak hangi durumu iyileştirebilir?</p><p>Hangi durumda mesajlar daha uzun bekleyebilir?</p><p>Ön tahmininizi iki cümleyle yazın.</p>')),'Mola sırasında hazır SystemView dosyasını ve kayıt masasını açın. Bağlı portu yalnız bir uygulamanın kullandığını kontrol edin.')
L('05 / Gerçek firmware','Aynı donanım, üç politika.','Bu haftanın A/B/C isimleri queue deneyini tanımlar; Hafta 2’deki öncelik varyantları değildir.',matrix+call('Sabitler: Producer P2, Consumer P1, Console P3 · Message 12 bayt · servis beklemesi 20 ms · UART 230400 baud.'),'Önemli: A/B/C aynı adlar ama yeni deney tanımları. Mevcut board ve FreeRTOS altyapısından türetildi; Hafta 2 projesi değiştirilmedi. B’nin daha büyük kapasitesi tek başına CPU hızını değiştirmez.')
L('05 / Canlı deney','Önce tahmin; sonra çalıştır.','Altı koşul: A/B/C × normal/yoğun yük.',flow(['Kayıt masasını aç','Varyant ve yük seç','Deneyi çalıştır','CSV + .SVDat al'])+cols(panel('Normal','<p>44 mesaj. Her gönderimden sonra 100 ms bekleme.</p>'),panel('Yoğun','<p>10 normal + 24 art arda girişim + 10 normal mesaj. Toplam yine 44.</p>'))+call('<a href="interface/index.html" target="_blank">Kayıt masasını aç ↗</a> · Seri port: ST-LINK VCP · Bu bilgisayarda doğrulanan port COM4.'),'Arayüz gerçek ölçüm verir; model göstermez. LD2 deney boyunca yanar. B1 butonunu kullanmayın: yük yazılımla tekrarlanabilir üretilir. Deney bittikten sonra kayıtları indirin.')
L('05 / Entegrasyon','ST-LINK ile SystemView akışı.','Kod çalışırken RAM’e kaydet; sonrasında aynı USB üzerinden dışarı al.',flow(['Task / IRQ / Queue<small>FreeRTOS trace hook’ları</small>','RAM / 32 KB<small>200 ms pencere</small>','ST-LINK VCP<small>Deney sonrası aktarım</small>','SystemView<small>.SVDat dosyasını aç</small>'])+call('SystemView içinde “J-Link ile canlı bağlan” kullanılmaz. Bu pakette ST-LINK firmware’i dönüştürülmez; snapshot dosyası açılır.'),'Normal yükte ilk mesaj çevresinden; burst yükte 11. mesajdan önce kayıt başlar. 200 ms bütün deneyi kapsamaz. CSV bütün 44 mesajı kapsar. UART Recorder protokolü değil, sonradan HEX aktarımı kullanılıyor.')
L('05 / Trace okuma','Bir mesajı dört olayla izle.','Aynı run ve id değerlerini eşleştir.',table(['Olay','Anlam','Bakılacak yer'],[['SEND_BEGIN','xQueueSend öncesi','Producer / çalışıyor mu?'],['SEND_OK / SEND_FAIL','API dönüşü ve send_us','Başarı veya timeout'],['RECEIVE','Consumer mesajı aldı','latency_us: üretimden almaya'],['DONE','Modellenen servis tamamlandı','20 ms bekleme sonrası']])+call('SystemView’de Events ve Timeline pencerelerini yan yana açın. Kullanıcı olayları W3 modülü altında açıklamalarıyla kaydedilir.'),'Kayıt başlamadan önce task’lar vardır; başlangıçta task listesi ve queue adı tekrar gönderilir. İlk önce Task adları Producer, Consumer, Console görünür mü kontrol edin. SysTick native port tarafından zaten izlenir; ikinci giriş/çıkış eklenmez.')
L('06 / Zaman sınırları','İki gecikmeyi karıştırmayalım.','Biri gönderme çağrısının süresi, diğeri mesajın tüketiciye ulaşma süresi.',cols(panel('send_call_us','<p>Gönderme çağrısı çevresindeki duvar saati.</p><p>Bloklanma, preemption ve yakındaki trace maliyetini içerebilir; saf CPU süresi değildir.</p>'),panel('generation_to_receive_us','<p>Mesaj üretim zamanından consumer’ın mesajı aldığı ana kadar.</p><p>C’de kuyrukta yer bekleme süresi de buna dahildir. Saf queue residence time değildir.</p>'))+call('Başarısız gönderime 0 ms gecikme atamayın. CSV’de alınmayan mesajın generation_to_receive_us alanı boştur.'),'timestamp DWT trace saati ile TIM2 ölçüm saati aynı sıfıra sahip değildir. Ham mutlak değerleri birbirinden çıkarmayın; aynı olay kimliğiyle eşleyip süreleri yorumlayın.')
L('06 / Kanıt','Bir tablo, üç ayrı soru.','Başarı sayısını gecikmeden ayrı okuyun.',table(['Karşılaştırma','Soru','Bedel'],[['A → B','Büyük buffer daha fazla mesaj kabul etti mi?','Bekleyen mesajların gecikmesi artabilir'],['A → C','Üretici bekleyince daha fazla mesaj kabul edildi mi?','Üreticinin döngüsü uzar'],['Trace açık → kapalı','İzleme ölçülen davranışı etkiliyor mu?','İz ek yükü sıfır kabul edilmez']])+call('Kaybı azaltan bir tasarım her task’ın zamanlama ihtiyacını iyileştirmiş olmayabilir.'),'Rakamları measurements/hardware dosyalarından okuyun. Gözlenen maksimum bir worst-case ispatı değildir. Kısa tek örnekten kesin üst sınır çıkarmayın.')
L('06 / Kapasite ve gecikme','Daha çok yer, daha çok bekleme olabilir.','Bekleyen mesaj sayısı × servis süresi, bir başlangıç sezgisi verir.',cols(panel('4 eleman','<div class="big">≈ 80 ms</div><p>Önünde dört servis işi varsa 4 × 20 ms. Scheduler ve tick etkileri dahil değil.</p>'),panel('16 eleman','<div class="big">≈ 320 ms</div><p>Önünde on altı servis işi varsa 16 × 20 ms. Bu bir ölçüm veya garanti değil.</p>'))+call('Kapasite kabul olasılığını etkiler. Kullanıcıya geç ulaşan veri hâlâ geç veridir.'),'Bu sayılar belirli bir kuyruk konumu varsayımıdır; kartta gözlenen maksimumla eşitlemeyin. Gecikmenin kuyruktaki konuma göre değiştiğini çizerek anlatın.')
L('06 / Dikkat','Critical section içinde bekleme yok.','Scheduler’ın ilerlemesi gereken bir işlemi kapalı bölgede beklemeyin.',cols(code('// YANLIŞ TASARIM\ntaskENTER_CRITICAL();\nxQueueSend(q, &msg, pdMS_TO_TICKS(20));\ntaskEXIT_CRITICAL();'),code('// BU DENEYDE\nBaseType_t result = xQueueSend(\n    q, &msg, pdMS_TO_TICKS(20));\n// Queue kendi iç senkronizasyonunu yapar.'))+call('Hafta 2’de 0 tick ile yapılan kritik bölge içi gönderimi, yalnız timeout’u değiştirerek bloklayan hale getirmeyin.',True),'Bu tuzak önemlidir: önceki referans enqueue içinde kritik bölüm kullanıyordu. Hafta 3 ayrı app.c’de queue’nun kendi eşzamanlılık mekanizmasına dayanır. ISR’den normal API çağrılmaz; FromISR sürümleri ve kesme önceliği kuralları ayrı konudur.')
L('07 / Bilgini sına','Büyük kuyruk her şeyi çözer mi?','Üretici sürekli 100 mesaj/s, tüketici 50 mesaj/s işleyebiliyor.', '<div class="panel quiz"><button data-answer="wrong">Kapasiteyi 16 yaparsak sistem sonsuza kadar kayıpsız çalışır.</button><button data-answer="correct">Daha büyük kuyruk taşmayı geciktirebilir; hız farkı sürerse yine dolar.</button><button data-answer="wrong">Task önceliğini artırınca tüketicinin bütün servis beklemesi ortadan kalkar.</button><p id="answer" role="status">Bir yanıt seçin.</p></div>','Sayılar öğretim senaryosudur. Öğrenciden sonuç yerine gerekçe isteyin: saniyede 50 mesaj birikiyor, sonlu alan sonunda doluyor.')
L('07 / Yeni ödev','Kuyruk dolunca sistemim ne yapıyor?','İlk hafta projesinin bir üretici–tüketici yolunu deneyle açıklayın.',cols(panel('Zorunlu','<p>A/B/C × normal/yoğun: altı deney.</p><p>A/yoğun için bir trace kapalı karşılaştırma.</p><p>Kod, ölçüm tablosu, iz kanıtı ve kısa anlatım.</p>'),panel('Kolay başlangıç','<p>Kendi projesinde uygun yol olmayanlar Hafta 3 referansını kullanabilir.</p><p>Yeni kart veya PC arayüzü yazılması gerekmiyor.</p>'))+call('<a href="odev-03.html" target="_blank">Ödev sunumunu aç ↗</a>'),'Her iki analiz aracını yeniden kurmayı zorunlu tutmayın. Bir çalışan araçla doğru açıklama yeterli. İkinci araçla karşılaştırma isteğe bağlı.')
L('07 / Kapanış','Bugünün üç cümlesi.','Veri akışını koddan ve izden açıklayabiliyorsanız hedefe ulaştık.',cols(panel('Kopya','<p>Queue, belirlenen boyuttaki veriyi kopyalar.</p>'),panel('Bekleme','<p>Boşta tüketici; doluyken üretici bloklanabilir.</p>'),panel('Bedel','<p>Kapasite ve timeout; kayıp, gecikme ve üretici zamanlamasını birlikte etkiler.</p>'))+call('Bir sonraki soru: İki task aynı kaynağı doğrudan kullanmak isterse ne olacak? → Mutex ve ortak kaynak yönetimi.'),'Çıkış: 1) Queue doluysa 0 tick ne yapar? 2) 20 ms kesin başarı mı? 3) Kapasite artışı neden daha büyük gecikmeyle birlikte görülebilir?')
L('Başvuru','Kaynaklar ve çalışma dosyaları.','Teknik anlatım resmî belgelerle, uygulama ise yerel kaynak kodla eşleştirildi.', '<div class="panel"><p><a href="https://www.freertos.org/Documentation/02-Kernel/02-Kernel-features/02-Queues-mutexes-and-semaphores/01-Queues" target="_blank" rel="noopener">FreeRTOS / Queues</a></p><p><a href="https://kb.segger.com/FreeRTOS_with_SystemView" target="_blank" rel="noopener">SEGGER / FreeRTOS with SystemView</a></p><p><a href="https://doc.segger.com/UM08027_SystemView.html" target="_blank" rel="noopener">SystemView User Guide / single-shot recording</a></p><p><a href="docs/SystemView_Kurulum.html">Yerel kurulum ve canlı anlatım rehberi</a></p><p><a href="docs/Dogrulama.html">Derleme, donanım ve arayüz doğrulaması</a></p><p class="mini">Kaynak kontrolü: 5 Ekim 2026 · firmware/src/app.c · firmware/src/app_trace.c<br>Sunum modelleri gerçek ölçüm olarak kullanılmaz. Gerçek kayıtlar measurements/hardware altında.</p></div>','İz dosyasını yorumlamadan önce overflow, timestamp ölçeği ve task adlarını kontrol edin. Hazır kayıtlar tek kart/sürüm/koşula aittir.')

